from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity):
        self.cap, self.d = capacity, OrderedDict()
    def get(self, key):
        if key not in self.d:
            return -1
        self.d.move_to_end(key)
        return self.d[key]
    def put(self, key, value):
        self.d[key] = value
        self.d.move_to_end(key)
        if len(self.d) > self.cap:
            self.d.popitem(last=False)


def run_ops(cap, ops):
    c, out = LRUCache(cap), []
    for op in ops:
        if op[0] == 'put':
            c.put(op[1], op[2])
        else:
            out.append(c.get(op[1]))
    return out

def chunk_words(text, size, overlap):
    w = text.split()
    out, i = [], 0
    while i < len(w):
        out.append(' '.join(w[i:i + size]))
        if i + size >= len(w):
            break
        i += size - overlap
    return out

import math
def top_k_similar(query, docs, k):
    qn = math.sqrt(sum(x*x for x in query))
    scores = []
    for i, v in docs.items():
        vn = math.sqrt(sum(x*x for x in v))
        if vn == 0 or qn == 0:
            continue
        scores.append((-(sum(a*b for a, b in zip(query, v)) / (qn*vn)), i))
    return [i for _, i in sorted(scores)[:k]]

