class TokenBucket:
    def __init__(self, capacity, refill_per_sec):
        self.cap, self.rate = capacity, refill_per_sec
        self.tokens, self.last = float(capacity), None
    def allow(self, now):
        if self.last is not None:
            self.tokens = min(self.cap, self.tokens + (now - self.last) * self.rate)
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False


def simulate(cap, rate, times):
    b = TokenBucket(cap, rate)
    return [b.allow(t) for t in times]

import json

def parse_tool_call(text):
    dec = json.JSONDecoder()
    i = text.find('{')
    while i != -1:
        try:
            obj, _ = dec.raw_decode(text[i:])
            if isinstance(obj, dict) and 'name' in obj:
                args = obj.get('arguments', {})
                if isinstance(args, str):
                    args = json.loads(args)
                return (obj['name'], args)
        except Exception:
            pass
        i = text.find('{', i + 1)
    return None

def dedupe(items):
    seen, out = set(), []
    for x in items:
        if x not in seen:
            seen.add(x); out.append(x)
    return out

def longest_unique(s):
    last, start, best = {}, 0, 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best

def flatten(x):
    out = []
    for i in x:
        out.extend(flatten(i) if isinstance(i, list) else [i])
    return out

