import functools
def retry(times):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **k):
            last = None
            for _ in range(times):
                try:
                    return fn(*a, **k)
                except Exception as e:
                    last = e
            raise last
        return wrapper
    return deco


def flaky(n_failures, times):
    state = {'calls': 0}
    @retry(times)
    def f():
        state['calls'] += 1
        if state['calls'] <= n_failures:
            raise ValueError('boom')
        return 'ok'
    try:
        return (f(), state['calls'])
    except ValueError:
        return ('failed', state['calls'])
